INSERT INTO lessons (week, title, author, minutes, xp, status, week_name, lesson_type, content, quiz_questions) VALUES
  -- Week 1: Awareness Phase
  (1, 'Your Body, Your Baseline', 'Coach Priya', 6, 50, 'active', 'Awareness', 'article',
   'Welcome to FitQuest! This first lesson is about understanding where you are right now — without judgment.\n\nWhy Baselines Matter\n\nResearch shows that people who track their starting metrics lose 2x more weight than those who don''t. Your baseline isn''t a grade — it''s a GPS pin. You can''t navigate without knowing your starting point.\n\nWhat to Track This Week\n\n1. Morning weight — step on the scale each morning before eating. Don''t worry about daily fluctuations; we''re looking for weekly trends.\n2. All meals — log breakfast, lunch, and dinner honestly. No meal is "bad"; we just need data.\n3. Your mood — check in each morning. Emotional patterns often predict eating patterns.\n\nThe Science of Awareness\n\nA 2019 study in the journal Obesity found that the simple act of food logging — even without changing what you eat — leads to measurable weight loss. Awareness creates a natural feedback loop that nudges you toward better choices.\n\nYour Action Items\n\n• Open the Scale task each morning and log your weight\n• Log every meal using the Meal task — photos work great\n• Complete your morning mood check-in\n• Do this for 7 consecutive days to complete your first challenge',
   '[{"question":"What did the 2019 Obesity journal study find about food logging?","options":["It only works with a strict diet","It leads to weight loss even without diet changes","It increases stress levels","It has no measurable effect"],"correct":1,"explanation":"Simply logging food creates an awareness feedback loop that naturally improves choices."},{"question":"Why do we track morning weight specifically?","options":["It is the most accurate daily measurement","Evening weight is always higher","Doctors require it","It burns more calories"],"correct":0,"explanation":"Morning weight before eating gives the most consistent measurement for tracking weekly trends."}]'),

  (1, 'Understanding Calories', 'Dr. Roy', 7, 50, 'active', 'Awareness', 'article',
   'Calories are simply units of energy. Every food gives you energy, and every activity uses energy. Weight management comes down to this energy balance.\n\nCalorie Deficit Explained\n\nTo lose weight, you need to consume fewer calories than your body uses. This is called a calorie deficit. A deficit of 500 calories per day leads to roughly 0.5 kg of weight loss per week.\n\nBut Not All Calories Are Equal\n\n100 calories of almonds and 100 calories of candy affect your body very differently:\n• Almonds: provide protein, healthy fats, and fiber — keeping you full for hours\n• Candy: spikes blood sugar, crashes energy, and leaves you hungry again in 30 minutes\n\nYour Daily Energy Budget\n\nThink of calories like a daily budget. You have a certain amount to "spend." The goal isn''t to spend as little as possible — it''s to spend wisely on foods that nourish you and keep you satisfied.\n\nPractical Tips\n\n• You don''t need to count every calorie obsessively\n• Focus on eating whole foods — they naturally keep calories in check\n• Use the meal logger to build awareness, not anxiety\n• Protein at every meal helps you stay full longer',
   '[{"question":"What is a calorie deficit?","options":["Eating zero calories","Consuming fewer calories than your body uses","Eating only protein","Skipping breakfast"],"correct":1,"explanation":"A calorie deficit means consuming less energy than your body burns, leading to weight loss."},{"question":"Why are 100 calories of almonds better than 100 calories of candy?","options":["Almonds have zero calories","Almonds provide protein, fats, and fiber that keep you full","Candy has more vitamins","There is no difference"],"correct":1,"explanation":"Almonds provide sustained nutrition and satiety, while candy causes energy spikes and crashes."}]'),

  -- Week 2: Movement
  (2, 'The Power of Walking', 'Coach Priya', 5, 50, 'locked', 'Movement', 'article',
   'Walking is the most underrated exercise for weight loss. It''s free, requires no equipment, and you can do it anywhere.\n\nWhy Walking Works\n\nWalking burns calories without triggering excessive hunger — unlike intense exercise which often makes you eat more afterward. A 30-minute brisk walk burns 150-200 calories.\n\nNEAT: Your Secret Weapon\n\nNon-Exercise Activity Thermogenesis (NEAT) accounts for 15-30% of your daily calorie burn. This includes walking, fidgeting, standing, and all movement outside formal exercise. Increasing your NEAT is often more impactful than gym sessions.\n\n5,000 Steps: Your Starting Goal\n\nWe start with 5,000 steps because it''s achievable for most people. The average sedentary person walks 2,000-3,000 steps daily, so 5,000 is a meaningful improvement without being overwhelming.\n\nHow to Build the Habit\n\n• Take a 10-minute walk after each meal (that''s 3,000+ steps right there)\n• Park farther away from entrances\n• Take phone calls while walking\n• Use stairs instead of elevators\n• Set hourly reminders to move for 2 minutes\n\nThe Step-Weight Connection\n\nA study from the University of Warwick found that people who walk 15,000 steps daily have BMIs in the healthy range regardless of other factors. Every step counts.',
   '[{"question":"What is NEAT?","options":["A type of diet plan","Non-Exercise Activity Thermogenesis — daily movement outside workouts","A heart rate zone","A meal planning method"],"correct":1,"explanation":"NEAT is all the calories you burn through daily movement that isn''t formal exercise, and it accounts for 15-30% of daily burn."},{"question":"Why is 5,000 steps a good starting goal?","options":["It is the maximum anyone should walk","It is achievable while being meaningfully more than sedentary levels","Doctors mandate it","It guarantees weight loss"],"correct":1,"explanation":"Most sedentary people walk 2,000-3,000 steps, so 5,000 is a realistic first improvement."}]'),

  -- Week 3: Sleep
  (3, 'Sleep: The Hidden Weight Loss Tool', 'Dr. Roy', 6, 50, 'locked', 'Recovery', 'article',
   'You can exercise perfectly and eat clean — but if you''re sleeping poorly, weight loss stalls. Sleep is when your body does its most important repair work.\n\nHow Sleep Affects Weight\n\nSleep deprivation increases ghrelin (hunger hormone) by 28% and decreases leptin (fullness hormone) by 18%. This means poor sleep literally makes you hungrier and less satisfied by food.\n\nThe Cortisol Connection\n\nWhen you don''t sleep enough, cortisol (stress hormone) stays elevated. High cortisol promotes fat storage, especially around the abdomen. It also increases cravings for high-sugar, high-fat foods.\n\n7 Hours: The Minimum\n\nResearch consistently shows that adults sleeping less than 7 hours are significantly more likely to be overweight. The sweet spot for weight loss is 7-9 hours.\n\nSleep Hygiene Essentials\n\n• Same bedtime and wake time every day — even weekends\n• No screens 30 minutes before bed (blue light suppresses melatonin)\n• Keep your room cool (18-20°C is optimal)\n• No caffeine after 2 PM\n• Use the app''s bedtime reminder to build consistency\n\nThe Recovery Equation\n\nSleep is when muscle repairs, hormones reset, and memories consolidate. Treat sleep as a non-negotiable part of your fitness program, not a luxury.',
   '[{"question":"How does sleep deprivation affect hunger hormones?","options":["It has no effect","It increases ghrelin and decreases leptin","It decreases both hormones","It only affects cortisol"],"correct":1,"explanation":"Poor sleep raises ghrelin (hunger) by 28% and lowers leptin (fullness) by 18%, making you hungrier."},{"question":"What is the minimum recommended sleep for weight loss?","options":["5 hours","6 hours","7 hours","10 hours"],"correct":2,"explanation":"Research consistently shows that less than 7 hours of sleep is associated with higher likelihood of being overweight."}]'),

  -- Week 4: Habits
  (4, 'Building Morning Routines', 'Coach Priya', 6, 60, 'locked', 'Habit Building', 'article',
   'Your morning sets the tone for the entire day. A consistent morning routine reduces decision fatigue and makes healthy choices automatic.\n\nThe Habit Loop\n\nEvery habit has three parts: Cue → Routine → Reward. For a morning check-in:\n• Cue: Your alarm goes off\n• Routine: Open the app, log mood, check today''s plan\n• Reward: Sense of control and clarity for the day\n\nWhy Mornings Matter for Weight Loss\n\nPeople who eat breakfast within 1 hour of waking have more stable blood sugar throughout the day. Stable blood sugar means fewer cravings and more consistent energy.\n\nThe 2-Minute Rule\n\nIf your routine feels hard, shrink it. James Clear''s 2-Minute Rule says: "When you start a new habit, it should take less than two minutes." Your morning check-in takes 30 seconds. That''s your anchor habit.\n\nBuild Your Stack\n\n1. Wake up → drink a glass of water (hydration after 8 hours of none)\n2. Step on the scale → log weight in the app\n3. Open FitQuest → complete morning mood check-in\n4. Review today''s tasks → know what''s coming\n5. Eat a protein-rich breakfast within 1 hour\n\nConsistency Over Perfection\n\nYou don''t need a perfect morning. You need a consistent one. Doing 80% of your routine every day beats doing 100% twice a week.',
   '[{"question":"What are the three parts of a habit loop?","options":["Plan, Execute, Review","Cue, Routine, Reward","Start, Middle, End","Think, Do, Rest"],"correct":1,"explanation":"Charles Duhigg''s habit loop: a Cue triggers the Routine, and a Reward reinforces it."},{"question":"What is the 2-Minute Rule?","options":["Exercise for exactly 2 minutes","New habits should take less than 2 minutes to start","Wait 2 minutes before eating","Meditate for 2 minutes daily"],"correct":1,"explanation":"James Clear''s principle: shrink new habits to under 2 minutes to reduce friction and build consistency."}]'),

  -- Week 5: Nutrition Deep Dive
  (5, 'Protein: Your Weight Loss Ally', 'Dr. Roy', 8, 60, 'locked', 'Nutrition', 'article',
   'Of all the macronutrients, protein has the strongest evidence for supporting weight loss. Here''s why it deserves center stage in your diet.\n\nThe Thermic Effect\n\nYour body burns 20-30% of protein calories just digesting them. Compare that to 5-10% for carbs and 0-3% for fat. Eating 100 calories of protein only nets you 70-80 usable calories.\n\nSatiety Power\n\nProtein is the most satiating macronutrient. Studies show that increasing protein from 15% to 30% of total calories causes people to eat 441 fewer calories per day — without trying.\n\nMuscle Preservation\n\nWhen you''re in a calorie deficit, your body can break down muscle for energy. Adequate protein (1.6-2.2g per kg body weight) protects your muscle mass, ensuring most weight loss comes from fat.\n\nPractical Protein Guide\n\n• Breakfast: Eggs, Greek yogurt, paneer, or protein smoothie\n• Lunch: Dal, chicken, fish, or tofu with vegetables\n• Dinner: Lean protein + vegetables + small portion of carbs\n• Snacks: Nuts, roasted chana, cheese, or protein bar\n\nThe 30g Rule\n\nAim for at least 30g of protein at each meal. This is roughly: 4 eggs, 150g chicken, 200g paneer, or 1.5 cups of dal. This ensures steady amino acid availability for muscle repair throughout the day.',
   '[{"question":"What percentage of protein calories are burned during digestion?","options":["0-3%","5-10%","20-30%","50%"],"correct":2,"explanation":"Protein has the highest thermic effect at 20-30%, meaning your body uses significant energy just digesting it."},{"question":"How much protein per kg of body weight is recommended during weight loss?","options":["0.5-0.8g","0.8-1.0g","1.6-2.2g","3.0-4.0g"],"correct":2,"explanation":"1.6-2.2g per kg body weight preserves muscle mass during a calorie deficit."}]'),

  -- Week 6: Midpoint
  (6, 'Your Halfway Checkpoint', 'Coach Priya', 5, 80, 'locked', 'Midpoint Review', 'article',
   'Congratulations — you''re halfway through the program! This is the perfect time to review what''s working and adjust what isn''t.\n\nThe Plateau Reality\n\nMany people hit a weight loss plateau around weeks 4-6. This is normal and NOT a sign of failure. Your body is adapting to its new routine. Plateaus typically last 1-3 weeks before weight loss resumes.\n\nWhy Plateaus Happen\n\n• Your metabolism adjusts to lower calorie intake\n• Water retention fluctuates with hormonal cycles\n• Muscle gain can offset fat loss on the scale\n• Your body becomes more efficient at daily activities\n\nBreaking Through\n\n1. Review your food logs — have portion sizes crept up?\n2. Increase daily steps by 1,000-2,000\n3. Add one new type of movement (yoga, swimming, cycling)\n4. Ensure you''re sleeping 7+ hours consistently\n5. Check stress levels — cortisol stalls weight loss\n\nCelebrate Non-Scale Victories\n\n• Clothes fitting better\n• More energy throughout the day\n• Better sleep quality\n• Improved mood and confidence\n• Stronger in daily activities\n\nThe data from your first 6 weeks is invaluable. Look at your weight chart, your streak history, and your XP progress. You''ve built habits that most people never start.',
   '[{"question":"Why do weight loss plateaus happen around weeks 4-6?","options":["You are doing everything wrong","Your body adapts to new calorie and activity levels","You need to stop exercising","Plateaus don''t actually exist"],"correct":1,"explanation":"Metabolic adaptation, water retention changes, and increased efficiency all contribute to normal plateaus."},{"question":"Which is a valid non-scale victory?","options":["The number on the scale","Clothes fitting better and more energy","Eating less than 500 calories","Exercising 4 hours daily"],"correct":1,"explanation":"Non-scale victories like better-fitting clothes, improved energy, and better sleep show real progress beyond weight."}]'),

  -- Week 7: Intensity
  (7, 'Stepping It Up: 8K and Beyond', 'Coach Priya', 6, 70, 'locked', 'Pushing Limits', 'article',
   'You''ve built a solid foundation. Now it''s time to push your limits and unlock the next level of results.\n\nFrom 5K to 8K Steps\n\nYour body has adapted to 5,000 steps. To continue progressing, we need progressive overload — gradually increasing the demand. 8,000 steps burns roughly 300-400 calories, a significant jump.\n\nThe Fat-Burning Zone\n\nAt moderate intensity (brisk walking, 8K steps pace), your body primarily burns fat for fuel. This is the "fat-burning zone" — 60-70% of your maximum heart rate. You should be able to talk but not sing.\n\nProgressive Overload for Walking\n\n• Week 7: Hit 8,000 steps on at least 5 days\n• Add incline — hills or stairs increase calorie burn by 50%\n• Try intervals — 2 minutes fast, 1 minute normal, repeat\n• Add a weighted backpack (2-5 kg) for extra resistance\n\nBeyond Walking\n\nConsider adding bodyweight exercises on alternate days:\n• Squats: 3 sets of 10\n• Push-ups: 3 sets of 5-10\n• Planks: 3 holds of 20-30 seconds\n• Lunges: 2 sets of 8 per leg\n\nThese build muscle, which increases your resting metabolic rate — you burn more calories even while sitting.',
   '[{"question":"What is progressive overload?","options":["Doing the same workout forever","Gradually increasing the demand on your body","Exercising until exhaustion daily","Reducing exercise over time"],"correct":1,"explanation":"Progressive overload means systematically increasing intensity to continue making progress as your body adapts."},{"question":"What heart rate zone primarily burns fat?","options":["90-100% max heart rate","80-90% max heart rate","60-70% max heart rate","Below 50% max heart rate"],"correct":2,"explanation":"The fat-burning zone is 60-70% of max heart rate — moderate intensity where you can talk but not sing."}]'),

  -- Week 8: Mindful Eating
  (8, 'Eating With Intent', 'Dr. Roy', 7, 70, 'locked', 'Nutrition Mastery', 'article',
   'By week 8, you know what to eat. Now let''s master how you eat. Mindful eating is the difference between people who lose weight and people who keep it off.\n\nThe Problem With Distracted Eating\n\nEating while watching TV or scrolling your phone increases calorie intake by 25-50%. Your brain doesn''t register fullness when it''s distracted, so you eat past the point of satisfaction.\n\nMindful Eating Principles\n\n1. Sit at a table for every meal — no standing, no car eating\n2. Put your phone away — one meal, one focus\n3. Chew each bite 15-20 times — this triggers satiety hormones\n4. Put your fork down between bites\n5. Stop eating when you''re 80% full (the Japanese "hara hachi bu" principle)\n\nThe Hunger Scale\n\nRate your hunger from 1-10 before eating:\n• 1-3: Starving (you''ve waited too long — you''ll overeat)\n• 4-5: Hungry (ideal time to eat)\n• 6-7: Satisfied (stop here)\n• 8-10: Overfull (you''ve gone too far)\n\nMeal Timing Matters\n\nEat your largest meal when you''re most active (usually lunch). Eating heavy late at night disrupts sleep and promotes fat storage. Try to finish dinner at least 2-3 hours before bedtime.\n\nLog Every Meal This Week\n\nUse the app to log all three meals with photos. Rate your hunger before and after. This builds the awareness muscle that makes mindful eating automatic.',
   '[{"question":"By how much does distracted eating increase calorie intake?","options":["5-10%","10-15%","25-50%","It has no effect"],"correct":2,"explanation":"Eating while watching TV or using your phone can increase consumption by 25-50% because your brain misses fullness signals."},{"question":"What is hara hachi bu?","options":["A Japanese exercise","Eating until 80% full","A fasting method","A cooking technique"],"correct":1,"explanation":"Hara hachi bu is the Okinawan practice of eating until 80% full, which prevents overeating and promotes longevity."}]'),

  -- Week 9: Full System
  (9, 'Putting It All Together', 'Coach Priya', 7, 80, 'locked', 'Integration', 'article',
   'This week is your dress rehearsal. You''ll combine every habit you''ve built into a complete daily system.\n\nYour Complete Daily System\n\nMorning:\n• Wake at consistent time → drink water\n• Step on scale → log weight\n• Morning mood check-in → review today''s plan\n• Protein-rich breakfast within 1 hour\n\nMidday:\n• 10-minute post-lunch walk\n• Log lunch with photo\n• Hydration check — aim for 4+ glasses by noon\n\nEvening:\n• Movement session or 8K+ steps completed\n• Mindful dinner — phone away, sit at table\n• Log dinner and snacks\n• Evening reflection in the app\n• Bedtime routine — screens off 30 min before sleep\n\nThe 5-Task Benchmark\n\nThis week''s challenge asks you to complete 5+ daily tasks on at least 4 days. This proves you can run the full system consistently.\n\nWhy Systems Beat Goals\n\nJames Clear wrote: "You don''t rise to the level of your goals. You fall to the level of your systems." A goal is "lose 10 kg." A system is "log meals, walk 8K steps, sleep 7 hours, check in daily." Goals give direction; systems give results.\n\nYour Identity Shift\n\nAt this point, you''re not just "trying to lose weight." You''re becoming a person who moves daily, eats mindfully, and takes care of their health. That identity shift is more powerful than any diet.',
   '[{"question":"According to James Clear, what determines your results?","options":["Your goals","Your motivation","Your systems","Your genetics"],"correct":2,"explanation":"You don''t rise to the level of your goals; you fall to the level of your systems. Systems create consistent results."},{"question":"How many daily tasks must you complete this week to meet the challenge?","options":["All tasks every day","5+ tasks on at least 4 days","Only walking","Just meal logging"],"correct":1,"explanation":"The Full System Week challenge requires completing 5+ daily tasks on at least 4 of the 7 days."}]'),

  -- Week 10: Peak Performance
  (10, 'The 10K Step Club', 'Coach Priya', 6, 90, 'locked', 'Peak Performance', 'article',
   'Welcome to the 10K Club. Hitting 10,000 steps daily is a major milestone that puts you in the top 20% of active adults.\n\nThe 10K Evidence\n\nA landmark 2019 study in JAMA Internal Medicine tracked 16,741 women and found that those walking 7,500+ steps daily had significantly lower mortality rates. At 10,000 steps, benefits plateau — meaning you''re hitting the optimal range.\n\nCalorie Burn at 10K\n\nAt 10,000 steps per day:\n• You walk approximately 7-8 km\n• You burn 400-500 extra calories\n• Over a week, that''s 2,800-3,500 calories — nearly 0.5 kg of fat\n\nStrategies to Hit 10K Consistently\n\n• Morning walk: 3,000 steps (25 min)\n• Post-lunch walk: 2,000 steps (15 min)\n• Evening walk: 3,000 steps (25 min)\n• Incidental movement: 2,000+ steps throughout the day\n\nMake It Social\n\nWalking with a partner increases adherence by 65%. Use the group feature to share your step counts and motivate each other. Competition is healthy when it''s friendly.\n\nBeyond Steps\n\nAt this point, consider adding structured exercise 2-3 times per week. Even 20 minutes of bodyweight training combined with your 10K steps creates a powerful fat-burning combination.',
   '[{"question":"At what step count do health benefits plateau according to research?","options":["5,000 steps","7,500 steps","10,000 steps","15,000 steps"],"correct":2,"explanation":"Research shows health benefits increase up to about 10,000 steps daily, after which additional benefits diminish."},{"question":"How many extra calories does 10,000 steps burn approximately?","options":["100-200","200-300","400-500","700-800"],"correct":2,"explanation":"10,000 steps burns roughly 400-500 extra calories, which over a week equals nearly 0.5 kg of fat loss."}]'),

  -- Week 11: Consistency
  (11, 'The Unbreakable Streak', 'Dr. Roy', 7, 100, 'locked', 'Identity Shift', 'article',
   'Week 11 is about proving to yourself that you can sustain every habit for 7 straight days. This is where habits become identity.\n\nThe 66-Day Myth\n\nPeople often cite 21 days to form a habit, but research from University College London shows the average is actually 66 days. At week 11, you''re at day 77 — well past the threshold. Your habits should feel increasingly automatic.\n\nNever Miss Twice\n\nThe most important rule for long-term habit maintenance: never miss twice in a row. Missing one day is human. Missing two days is the start of a new (bad) habit. If you miss a check-in on Monday, make Tuesday non-negotiable.\n\nYour 7-Day Perfect Week\n\nThis week''s challenge: complete ALL daily tasks for 7 consecutive days:\n• Morning weight + mood check-in\n• All 3 meals logged\n• 10K+ steps\n• 7+ hours sleep\n• Evening reflection\n\nThe Compound Effect\n\nSmall daily improvements compound over time. If you improve just 1% each day:\n• After 30 days: 35% better\n• After 77 days (now): 116% better\n• After 365 days: 3,778% better\n\nThis is why consistency beats intensity. A moderate effort every single day outperforms heroic efforts once a week.',
   '[{"question":"How many days does research say it actually takes to form a habit?","options":["21 days","30 days","66 days on average","Exactly 90 days"],"correct":2,"explanation":"University College London research found the average is 66 days, not the commonly cited 21 days."},{"question":"What is the most important rule for habit maintenance?","options":["Never miss a single day","Never miss twice in a row","Only do habits on weekdays","Change habits every month"],"correct":1,"explanation":"Missing once is human; missing twice starts a new pattern. The key rule is to never miss two days consecutively."}]'),

  -- Week 12: Transformation
  (12, 'Your Transformation Story', 'Coach Priya', 8, 150, 'locked', 'Transformation', 'article',
   'You made it to Week 12. This isn''t the end — it''s the beginning of who you''ve become.\n\nLook Back at Your Data\n\nOpen your weekly progress screen and review:\n• Starting weight vs. current weight\n• Week 1 step count vs. now\n• Your longest streak\n• Total XP earned\n• Badges collected\n\nEvery number tells a story of discipline, growth, and resilience.\n\nThe Transformation Is Internal\n\nThe weight you''ve lost matters, but the real transformation is invisible:\n• You now default to healthy choices\n• You move your body daily without thinking about it\n• You listen to hunger cues instead of emotions\n• You prioritize sleep as part of fitness\n• You have a community that supports your journey\n\nWhat Happens After Week 12?\n\nThis program ends, but your system doesn''t. You have everything you need:\n• A morning routine that anchors your day\n• Meal logging awareness that prevents mindless eating\n• A step goal that keeps you active\n• Sleep habits that support recovery\n• A community for accountability\n\nMaintenance Mode\n\nResearch shows that people who maintain their habits for 12+ weeks are 80% more likely to sustain results after 1 year. You''ve crossed that threshold.\n\nYour Next Chapter\n\n• Set a new step goal (12K? 15K?)\n• Try a new sport or activity\n• Mentor someone starting their journey\n• Keep logging — awareness is forever\n\nThank you for trusting FitQuest with your transformation. Now go live it.',
   '[{"question":"How much more likely are you to sustain results after maintaining habits for 12+ weeks?","options":["20% more likely","50% more likely","80% more likely","100% guaranteed"],"correct":2,"explanation":"Research shows 12+ weeks of consistent habits makes you 80% more likely to sustain results at the 1-year mark."},{"question":"What is the most important transformation from this program?","options":["The number on the scale","Building automatic healthy habits and identity change","Having a perfect diet","Exercising every single day"],"correct":1,"explanation":"The real transformation is internal — healthy defaults, daily movement, and a new identity as someone who takes care of their health."}]')

ON CONFLICT DO NOTHING;
